<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,ref} from 'vue'; import Hls from 'hls.js'; import type {VideoSource,WatchEntry,SourceKind} from './types'; import {loadSources,saveSources,loadHistory,saveHistory} from './store';
const sources=ref<VideoSource[]>(loadSources()),history=ref<WatchEntry[]>(loadHistory()),tab=ref<'home'|'favorites'|'history'|'settings'>('home'),query=ref(''),name=ref(''),url=ref(''),kind=ref<SourceKind>('website'),category=ref('视频'),playerUrl=ref(''),playerTitle=ref(''),video=ref<HTMLVideoElement|null>(null),notice=ref('欢迎使用 Video Hub。添加你有权访问的网站或媒体地址即可开始。'),health=ref<Record<string,string>>({}); let hls:Hls|null=null;
const visible=computed(()=>{const list=tab.value==='favorites'?sources.value.filter(x=>x.favorite):sources.value;const q=query.value.trim().toLowerCase();return list.filter(x=>!q||[x.name,x.url,x.category].some(v=>v.toLowerCase().includes(q)))});
function validUrl(raw:string){try{const u=new URL(raw.trim());return ['http:','https:'].includes(u.protocol)?u.toString():null}catch{return null}}
function add(){const safe=validUrl(url.value);if(!name.value.trim()||!safe){notice.value='请填写名称和有效的 HTTP/HTTPS 地址。';return}if(sources.value.some(x=>x.url===safe)){notice.value='该地址已经存在。';return}sources.value.unshift({id:crypto.randomUUID(),name:name.value.trim(),url:safe,kind:kind.value,category:category.value||'其他',authorized:true,favorite:false,createdAt:Date.now()});saveSources(sources.value);name.value='';url.value='';notice.value='来源已添加。请确认你拥有访问内容及接口的合法授权。'}
function remove(id:string){sources.value=sources.value.filter(x=>x.id!==id);saveSources(sources.value)}
function favorite(s:VideoSource){s.favorite=!s.favorite;saveSources(sources.value)}
function open(s:VideoSource){if(s.kind==='media')play(s.url,s.name);else window.open(s.url,'_blank','noopener,noreferrer')}
function play(raw:string,title='媒体播放'){const safe=validUrl(raw);if(!safe){notice.value='播放地址无效，仅支持 HTTP/HTTPS。';return}playerUrl.value=safe;playerTitle.value=title;history.value=[{id:crypto.randomUUID(),title,url:safe,watchedAt:Date.now()},...history.value.filter(x=>x.url!==safe)].slice(0,100);saveHistory(history.value);notice.value='已载入媒体。若播放失败，请确认链接可直接访问且服务端允许跨域。';void nextTick(attach)}
function attach(){if(!video.value||!playerUrl.value)return;hls?.destroy();hls=null;if(/\.m3u8(?:$|\?)/i.test(playerUrl.value)&&Hls.isSupported()){hls=new Hls({enableWorker:true});hls.loadSource(playerUrl.value);hls.attachMedia(video.value);hls.on(Hls.Events.ERROR,(_,d)=>{if(d.fatal)notice.value='HLS 播放失败，请检查地址、授权和 CORS。'})}else{video.value.src=playerUrl.value;video.value.load()}}
function check(s:VideoSource){const c=new AbortController();health.value[s.id]='检测中';const t=setTimeout(()=>c.abort(),5000);fetch(s.url,{method:'HEAD',mode:'cors',signal:c.signal}).then(r=>health.value[s.id]=r.ok?'可访问':`HTTP ${r.status}`).catch(()=>health.value[s.id]='无法判断（CORS/网络限制）').finally(()=>clearTimeout(t))}
function clear(){history.value=[];saveHistory(history.value)}
onBeforeUnmount(()=>hls?.destroy());
</script>
<template><div class="shell"><aside class="side"><div class="brand"><b>▶</b><div><strong>VIDEO HUB</strong><small>个人视频中心</small></div></div><nav><button :class="{on:tab==='home'}" @click="tab='home'">⌂　发现</button><button :class="{on:tab==='favorites'}" @click="tab='favorites'">☆　我的收藏</button><button :class="{on:tab==='history'}" @click="tab='history'">◷　播放历史</button><button :class="{on:tab==='settings'}" @click="tab='settings'">⚙　来源管理</button></nav><small class="local">● 本地数据已启用</small></aside><main><header><div><small class="eyebrow">YOUR MEDIA SPACE</small><h1>{{({home:'发现内容',favorites:'我的收藏',history:'播放历史',settings:'来源管理'} as const)[tab]}}</h1></div><input class="search" v-model="query" placeholder="搜索来源、分类或网址"/></header>
<section v-if="tab==='home'||tab==='favorites'"><div class="hero"><div><small class="eyebrow">ONE PLACE, YOUR CONTENT</small><h2>把常用视频入口<br/><em>收纳在一起。</em></h2><p>管理你有权访问的网站与媒体，使用统一播放器播放直接媒体链接。</p></div><span class="orb">▶</span></div><div class="section"><div><h3>{{tab==='favorites'?'收藏来源':'常用入口'}}</h3><small>{{visible.length}} 个来源</small></div><button class="link" @click="tab='settings'">＋ 添加来源</button></div><div class="grid"><article v-for="s in visible" :key="s.id" class="card"><div class="cardtop"><span class="icon">{{s.kind==='media'?'♫':s.name.slice(0,1)}}</span><button class="star" :class="{chosen:s.favorite}" @click="favorite(s)">★</button></div><h4>{{s.name}}</h4><small>{{s.category}} · {{s.kind==='media'?'媒体地址':'网站入口'}}</small><div class="actions"><button class="primary mini" @click="open(s)">{{s.kind==='media'?'立即播放':'打开网站'}} ↗</button><button class="ghost" @click="check(s)">检测</button></div><small v-if="health[s.id]" class="health">{{health[s.id]}}</small></article><div v-if="!visible.length" class="empty">没有匹配来源，请到来源管理添加。</div></div></section>
<section v-else-if="tab==='history'"><div class="section"><div><h3>最近播放</h3><small>记录保存在当前设备</small></div><button class="link" @click="clear">清空历史</button></div><div class="list"><article v-for="x in history" :key="x.id" class="row"><span class="icon">▶</span><div class="rowtext"><b>{{x.title}}</b><small>{{x.url}}</small><small>{{new Date(x.watchedAt).toLocaleString()}}</small></div><button class="primary mini" @click="play(x.url,x.title)">继续播放</button></article><div v-if="!history.length" class="empty">暂无播放记录。</div></div></section>
<section v-else class="settings"><div class="panel"><h3>添加视频来源</h3><small>网站入口或可直接播放的媒体 URL</small><form @submit.prevent="add"><label>来源名称<input v-model="name" required maxlength="60" placeholder="例如：我的媒体库"/></label><label>访问地址<input v-model="url" required type="url" placeholder="https://example.com 或媒体 URL"/></label><div class="twocol"><label>类型<select v-model="kind"><option value="website">网站入口</option><option value="media">直接媒体</option></select></label><label>分类<input v-model="category" maxlength="30"/></label></div><p class="hint">仅添加你有权访问和分发的内容。本项目不提供付费墙绕过、DRM 破解或未授权解析功能。</p><button class="primary">＋ 保存来源</button></form></div><div class="panel"><h3>已配置来源 <small>· {{sources.length}} 个</small></h3><div class="list"><div v-for="s in sources" :key="s.id" class="managed"><div><b>{{s.name}}</b><small>{{s.url}}</small></div><button class="danger" @click="remove(s.id)">删除</button></div><div v-if="!sources.length" class="empty">尚未添加来源。</div></div></div></section>
<section class="player"><div class="section"><div><small class="eyebrow">PLAYER</small><h3>{{playerTitle||'统一媒体播放器'}}</h3></div><small>HTML5 · HLS</small></div><video v-if="playerUrl" ref="video" controls playsinline :src="playerUrl"></video><div v-else class="placeholder"><b>▶</b><strong>播放你有权访问的媒体</strong><small>支持浏览器原生格式及 HLS（.m3u8）</small></div><form class="playform" @submit.prevent="play(playerUrl,playerTitle||'媒体播放')"><input v-model="playerUrl" type="url" placeholder="粘贴直接媒体地址（MP4 / WebM / M3U8）"/><button class="primary">载入播放</button></form></section><footer>{{notice}}<span>Video Hub · 0.1.0</span></footer></main></div></template>